import os, json, re
from copy import deepcopy

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')
    G = {}
    # Parse all demo pairs, test input and outputs
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        content_start = m.end()
        lines = [line.strip() for line in t[content_start:].split('\n')[:h]]
        grid = [[int(x) for x in rows] for rows in lines]
        # Extract label type
        label_type = "demo" if "Demo pair" in m.group(1) else "test"
        instance_num = re.search(r'pair (\d+)', m.group(1))
        demo_id = f"{label_type}_{instance_num.group(1)}" if instance_num else label_type

        if k not in G:
            if label_type == "test":
                G["test"] = {"rows": h, "cols": w, "grid": grid}
            else:
                demo_info = {k.lower(): demo_id}
                G[demo_id] = {"rows": h, "cols": w, "grid": grid, **demo_info}
    return G

G = load()
print("Loaded:", sorted(G.keys()))
for key, val in sorted(G.items()):
    print(f"\n{key}: {val.get('grid')}")

import os, re
