def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n','\n')

    G = {}
    current_key = None
    current_rows = []

    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        label = m.group(1)
        h, w = int(m[2]), int(m[3])

        # Find next occurrence of the same pattern to know where this grid ends
        search_start = m.end()
        content_end = None
        for m2 in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \(', t[search_start:]):
            if abs(int(m2.group().split()[1]) - h) > 10:  # heuristic to find end of current grid
                content_end = search_start + m2.start()
                break
        if content_end is None:
            content_end = search_start + len(t) // 2

        if current_key is not None and current_rows:
            grid = [[int(x) for x in r.strip().split()] for r in current_rows]
            if label.startswith("Demo pair"):
                inst_num = int(re.search(r'pair (\d+)', label).group(1))
                G[f"demo{inst_num}"] = {"rows": h, "cols": w, "grid": grid}
            else:
                G["test"] = {"rows": h, "cols": w, "grid": grid}

        current_key = label
        current_rows = []

    return G

