        rows = []
        for line in lines[:h]:
            if line:
                parts = line.replace('\\', '').split()
                rows.append([int(x) for x in parts])

        grids[label] = {'rows': len(rows), 'cols': len(rows[0]) if rows else 0, 'grid': rows}

    return grids

