import os, json, re
from copy import deepcopy

def load():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read()

    # Find all custom messages
    matches = re.findall(r'"custom_message"[^}]+\{"type":"puzzle"\}', t)

    grids = {}
    for match in matches:
        # Extract grid info from this message
        if 'Test input' in match:
            # Parse test input dimensions and grid
            dim_match = re.search(r'Test input \(1x?(\d+)\):', match)
            if dim_match:
                w = int(dim_match.group(1))
                h = w  # Assuming square for now
            else:
                continue

            # Find grid content (3x3 based on Test input)
            lines = re.findall(r'\s*\n\s*(\d+) (\d+) (\d+)', match)
            if len(lines) == 9:
                grid = [[int(x) for x in lines[i:i+3]] for i in range(0,9,3)]
                grids['test'] = {'rows': 3, 'cols': 3, 'grid': grid}

        if 'Demo pair' in match:
            inst_num = re.search(r'Demo pair (\d+)', match).group(1)

            # Get input part
            input_part = re.search(r'Demo pair \d+ input \(1x?(\d+)\):(.*?)(?=Demo|Test|$)', match, re.DOTALL)
            output_part = re.search(r'Demo pair \d+ output \(1x?(\d+)\):', match)

            # Parse input grid
            input_lines = re.findall(r'\s*\n\s*(\d+) (\d+) (\d+)', input_part.group() if input_part else match)
            if len(input_lines) >= 9:
                input_grid = [[int(x) for x in input_lines[i:i+3]] for i in range(0,9,3)]

                # Parse output grid  
                output_lines = re.findall(r'\s*\n\s*(\d+) (\d+) (\d+)', output_part.group() if output_part else match)
                if len(output_lines) >= 25:
                    output_grid = [[int(x) for x in output_lines[i:i+5]] for i in range(0,25,5)]

                    grids[f"demo{inst_num}"] = {
                        'input_rows': 3, 'input_cols': 3, 'input_grid': input_grid,
                        'output_rows': 5, 'output_cols': 5, 'output_grid': output_grid
                    }

    return grids

G = load()
print("Loaded keys:", sorted(G.keys()))
for key in sorted(G.keys()):
    print(f"\n{key}:")
    info = G[key]
    for label, g in [('input', info.get('input_grid')), ('output', info.get('output_grid'))]:
        print(f"  {label}: {g}")

import json

def transform(input_grid):
    """Transform 3x3 input to 5x5 output."""
    # Find cells that have non-5 values (these determine the output)
    # Based on analysis: (0,0), (1,1), (1,2), (2,0), (2,2)

    survivors = []
    for i in range(3):
        for j in range(3):
            val = input_grid[i][j]
            # Check if this cell contributes (not 5)
            if val != 5:
                survivors.append((i, j, val))

    output = [[5 for _ in range(5)] for _ in range(5)]

    for i, j, val in survivors:
        if i == 0 and j == 0:
            # Top-left 2x2 block
            for r in range(2):
                for c in range(2):
                    output[r][c] = val
        elif i == 1 and j == 1:
            # Center 1x1
            output[2][2] = val
        elif i == 1 and j == 2:
            # Middle row, right part - fills cols 3-4 at row 2
            for c in range(3, 5):
                output[2][c] = val
        elif i == 2 and j == 0:
            # Bottom row, left part - fills rows 3-4 at col 0
            for r in range(3, 5):
                output[r][0] = val
        elif i == 2 and j == 2:
            # Bottom-right 2x2
            for r in range(3, 5):
                for c in range(3, 5):
                    output[r][c] = val

    return output

# Test on demo pair 1
demo_input = [[6, 5, 5], [5, 1, 7], [4, 5, 2]]
demo_output_expected = [[6, 6, 5, 5, 5], [6, 6, 5, 5, 5], [5, 5, 1, 7, 7], [4, 4, 5, 2, 2], [4, 4, 5, 2, 2]]
demo_output_actual = transform(demo_input)

print("Demo pair 1 test:")
print(f"Expected:\n{demo_output_expected}")
print(f"Actual:\n{demo_output_actual}")
print(f"Match: {demo_output_actual == demo_output_expected}")

# Test on test input
test_input = [[1, 2, 5], [7, 3, 6], [7, 6, 5]]
test_output = transform(test_input)

print("\nTest input result:")
print(json.dumps(test_output))

